// Level: unit
/**
 * The generated rule files are current, untouched, and in the form measured to reach a
 * Cursor agent.
 *
 * A shipped rule's text lives in .tropis/rules/ and its area in .claude/rule-areas.json;
 * generate-rules.mjs writes the Claude Code file and the Cursor file from them, and a Cursor
 * file for each of the project's own rules. This guard runs its check mode — so a changed
 * area or text without a regeneration, or a hand edit of a generated file, fails the
 * project's checks — and compares every Cursor file's front matter with the measured form.
 * Copied into every set-up project by set-up-project.sh.
 */
import { spawnSync } from 'node:child_process';
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  areaProblems, renderClaude, renderCursor, checkStamp,
  ADDITIONS_SEPARATOR, joinAdditions, additionsProblem,
} from '../scripts/rule-areas.js';

const here = dirname(fileURLToPath(import.meta.url));
// In a set-up project this file is .tropis/guards/, two levels below the root.
// check-conformance.sh points it at a composed fixture instead.
const root = process.env.FRAMEWORK_ROOT ?? resolve(here, '../..');
const cursorDir = resolve(root, '.cursor/rules');

describe('generated rules', () => {
  it('are what the sources would write, and untouched', () => {
    const r = spawnSync('node', [resolve(root, '.tropis/scripts/generate-rules.mjs'), '--check'], { encoding: 'utf8' });
    // On failure the report names each file and says whether it was edited by hand or is stale.
    expect(r.status === 0 ? '' : r.stderr).toBe('');
  });

  it('give every Cursor file exactly the measured front matter', () => {
    const bad = [];
    for (const file of readdirSync(cursorDir).filter((f) => f.endsWith('.mdc'))) {
      const name = file.replace(/\.mdc$/, '');
      const text = readFileSync(resolve(cursorDir, file), 'utf8');
      const m = /^---\n([^\n]*)\n([^\n]*)\n([^\n]*)\n---\n\n/.exec(text);
      const ok = m
        && m[1] === `description: ${name} rules (generated — do not edit)`
        && /^globs: [^,\s][^,]*(, [^,\s][^,]*)*$/.test(m[2])
        && !/^globs: \[|"/.test(m[2])
        && m[3] === 'alwaysApply: false';
      if (!ok) bad.push(file);
    }
    expect(bad).toEqual([]);
  });
});

describe('areas file', () => {
  const shipped = ['catalogs', 'tests'];
  it('accepts one non-empty list per shipped rule', () => {
    expect(areaProblems({ catalogs: ['a'], tests: ['b/**'] }, shipped)).toEqual([]);
  });
  it('reports a missing rule, an unknown rule, an empty list and a comma', () => {
    const p = areaProblems({ catalogs: [], tests: ['a,b'], other: ['x'] }, shipped).join('\n');
    expect(p).toContain('"catalogs" must be a non-empty array');
    expect(p).toContain('comma');
    expect(p).toContain('"other" is not a shipped rule');
    expect(areaProblems({ catalogs: ['a'] }, shipped).join()).toContain('no area for the shipped rule "tests"');
  });
});

describe('rule rendering', () => {
  it('writes the Claude Code file as header, text, hash line', () => {
    const out = renderClaude(['a/**', '**/*.test.*'], 'Text.\n\n');
    expect(out.startsWith('---\npaths: ["a/**","**/*.test.*"]\n---\nText.\n<!-- generated by ')).toBe(true);
    expect(checkStamp(out)).toEqual({ generated: true, intact: true });
  });

  it('writes the Cursor file with unquoted comma-separated globs and no other field', () => {
    const out = renderCursor('tests', ['**/*.test.*', 'test/**'], 'Body.\n');
    expect(out.split('\n').slice(0, 7)).toEqual([
      '---',
      'description: tests rules (generated — do not edit)',
      'globs: **/*.test.*, test/**',
      'alwaysApply: false',
      '---',
      '',
      'Body.',
    ]);
  });

  it('writes identical bytes for identical input', () => {
    expect(renderCursor('a', ['x/**'], 'B\n')).toBe(renderCursor('a', ['x/**'], 'B\n'));
  });

  it('tells a hand-edited file from an untouched one and from one with no hash line', () => {
    const out = renderClaude(['a/**'], 'Text.\n');
    expect(checkStamp(out.replace('Text.', 'Text, changed.')).intact).toBe(false);
    expect(checkStamp(out.replace('Text.', 'Text, changed.')).generated).toBe(true);
    expect(checkStamp('---\npaths: ["a/**"]\n---\nText.\n')).toEqual({ generated: false, intact: false });
  });
});

describe('rule additions', () => {
  it('joins additions after the shipped text, under the separator', () => {
    const out = joinAdditions('# Tests\n\nShipped.\n\n', '\n\nOurs.\n');
    expect(out).toBe(`# Tests\n\nShipped.\n\n${ADDITIONS_SEPARATOR}\n\nOurs.\n`);
  });
  it('leaves the text untouched with no additions, or empty ones', () => {
    for (const a of [null, '', '  \n\n']) expect(joinAdditions('# T\n\nS.\n\n', a)).toBe('# T\n\nS.\n\n');
  });
  it('ends in one newline whatever the additions end in', () => {
    expect(joinAdditions('S.', 'Ours.')).toBe(joinAdditions('S.', 'Ours.\n\n\n'));
  });
  it('says the additions win and that the agent tells the operator', () => {
    expect(ADDITIONS_SEPARATOR).toContain('follow the text below');
    expect(ADDITIONS_SEPARATOR).toContain('tell the operator');
  });
  it('refuses a header, an own rule\'s name and an unknown name', () => {
    const shipped = ['catalogs', 'tests'];
    expect(additionsProblem('tests', 'Ours.\n', shipped, ['app'])).toBeNull();
    expect(additionsProblem('tests', '---\npaths: ["x/**"]\n---\nOurs.\n', shipped, [])).toContain('carries no header');
    expect(additionsProblem('app', 'Ours.\n', shipped, ['app'])).toContain('.claude/rules/app.md itself');
    const unknown = additionsProblem('pricing', 'Ours.\n', shipped, []);
    expect(unknown).toContain('no shipped rule is named "pricing"');
    expect(unknown).toContain('catalogs, tests');
  });
});
